import type { createA19ContextualDraftPolicy } from "@heroesofcrypto/common/src/ai/setup/a19_contextual_draft_policy";

type NativePolicy = ReturnType<typeof createA19ContextualDraftPolicy>;
export type TimingMode = "current" | "contextual-off" | "map-visible";

export function contextualTimingPolicy(native: NativePolicy, mode: TimingMode): NativePolicy {
    if (mode === "current") return native;
    const defer = (map: number | undefined) => mode === "contextual-off" || map === undefined;
    return Object.freeze({
        ...native,
        bundle: (...args: Parameters<NativePolicy["bundle"]>) =>
            defer(args[2].scouting.map)
                ? { choice: args[1], consumeOverride: false }
                : native.bundle(...args),
        creature: (...args: Parameters<NativePolicy["creature"]>) =>
            defer(args[2].scouting.map)
                ? { choice: args[1], consumeOverride: false }
                : native.creature(...args),
    });
}
